/* @lc app=leetcode id=3669 lang=kotlin */ class Solution { fun g(ds: List<Int>, n: Int, k: Int, lo: Int): List<List<Int>> = if (k == 1) (if (n >= lo) listOf(listOf(n)) else listOf()) else ds.filter { it >= lo && n % it == 0 }.flatMap { d -> g(ds, n / d, k - 1, d).map { listOf(d) + it } } fun minDifference(n: Int, k: Int): IntArray = (1..n).filter { n % it == 0 }.let { ds -> g(ds, n, k, 1).minBy { it.last() - it.first() }.toIntArray() } }